python3 - <<'PY'
from pathlib import Path

h = Path('src/climate/native/NativeI2cBus.h')
s = h.read_text()
old = '''  esp_err_t addDevice(std::uint8_t address, std::uint32_t clock_hz,
                      i2c_master_dev_handle_t& device) noexcept;
'''
new = old + '''  esp_err_t probe(std::uint8_t address, int timeout_ms = 100) noexcept;
'''
assert old in s and 'esp_err_t probe(' not in s
h.write_text(s.replace(old, new))

cpp = Path('src/climate/native/NativeI2cBus.cpp')
s = cpp.read_text()
needle = '''esp_err_t NativeI2cBus::addDevice(std::uint8_t address, std::uint32_t clock_hz,
                                  i2c_master_dev_handle_t& device) noexcept {
'''
assert needle in s and 'NativeI2cBus::probe(' not in s
insert_before = '''
} // namespace growbox::app::climate_io::native
'''
method = '''
esp_err_t NativeI2cBus::probe(std::uint8_t address, int timeout_ms) noexcept {
  if (bus_ == nullptr) {
    return ESP_ERR_INVALID_STATE;
  }
  return i2c_master_probe(bus_, address, timeout_ms);
}
'''
assert insert_before in s
cpp.write_text(s.replace(insert_before, method + insert_before))

scd = Path('src/climate/native/Scd41InsideSource.cpp')
s = scd.read_text()
assert '#include <driver/i2c_master.h>\n' in s
s = s.replace('#include <driver/i2c_master.h>\n', '#include <driver/i2c_master.h>\n#include <esp_log.h>\n')
assert 'constexpr std::uint8_t kScd41Address = 0x62U;
' in s
s = s.replace('constexpr std::uint8_t kScd41Address = 0x62U;
', 'constexpr char kScd41Tag[] = "scd41";
constexpr std::uint8_t kScd41Address = 0x62U;
')
old = '''  const int16_t error = scd4x_start_periodic_measurement();
  available_ = error == 0;
'''
new = '''  const int16_t error = scd4x_start_periodic_measurement();
  if (error != 0) {
    ESP_LOGW(kScd41Tag, "start_periodic_measurement failed: %d", static_cast<int>(error));
  }
  available_ = error == 0;
'''
assert old in s
scd.write_text(s.replace(old, new))

rt = Path('src/climate/ClimateV6RealInputRuntime.cpp')
s = rt.read_text()
assert '#include <esp_log.h>\n' in s
s = s.replace('#include <esp_log.h>\n', '#include <esp_err.h>\n#include <esp_log.h>\n')
old = '''  native::NativeI2cBus i2c(GROWBOX_I2C_SDA_GPIO, GROWBOX_I2C_SCL_GPIO);
  const bool i2c_ready = i2c.begin() == ESP_OK;

  native::Scd41InsideSource inside;
'''
new = '''  native::NativeI2cBus i2c(GROWBOX_I2C_SDA_GPIO, GROWBOX_I2C_SCL_GPIO);
  const bool i2c_ready = i2c.begin() == ESP_OK;
  const esp_err_t scd41_probe = i2c_ready ? i2c.probe(0x62U) : ESP_ERR_INVALID_STATE;
  const esp_err_t rtc_probe = i2c_ready ? i2c.probe(0x68U) : ESP_ERR_INVALID_STATE;
  ESP_LOGI(kTag, "I2C probe: scd41_0x62=%s ds3231_0x68=%s", esp_err_to_name(scd41_probe),
           esp_err_to_name(rtc_probe));

  native::Scd41InsideSource inside;
'''
assert old in s
rt.write_text(s.replace(old, new))
PY
.venv/bin/pre-commit run --files src/climate/native/NativeI2cBus.h src/climate/native/NativeI2cBus.cpp src/climate/native/Scd41InsideSource.cpp src/climate/ClimateV6RealInputRuntime.cpp && git diff --check
